/* From Uiverse.io by SilasRodrigues19 - Tags: loader */
.__UIV_SCOPE__ .loader {
  z-index: 20;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: visible;
}

.__UIV_SCOPE__ .loader span {
  width: 50px;
  height: 50px;
  margin: -5px;
  animation: dots_411 1.5s infinite ease-in-out;
}

.__UIV_SCOPE__ .loader span:nth-child(1) {
  -webkit-animation-delay: -.40s;
  animation-delay: -.40s;
}

.__UIV_SCOPE__ .loader span:nth-child(2) {
  -webkit-animation-delay: -.25s;
  animation-delay: -.25s;
}

.__UIV_SCOPE__ .loader span:nth-child(3) {
  -webkit-animation-delay: -.10s;
  animation-delay: -.10s;
}

@keyframes dots_411 {
  5% {
    opacity: 0;
  }

  0%, 80%, 100% {
    -webkit-transform: scale(0);
    transform: scale(0);
  }

  40% {
    -webkit-transform: scale(.8);
    transform: scale(.8);
  }
}
